"use strict";

var exportedApply = require("./apply-export");
var guardedApply = require("./apply-guarded");
var exportedProto = require("./proto-export");

var localApply = Reflect.apply;
var maybeApply = typeof Reflect !== "undefined" && Reflect.apply;
var held = { apply: Reflect.apply, proto: Reflect.getPrototypeOf };

function sum(a, b) {
  return this.base + a + b;
}

function describe(thunk) {
  try {
    var result = thunk();
    return typeof result === "string" ? result : String(JSON.stringify(result));
  } catch (e) {
    return e.name + ": " + e.message;
  }
}

function through(f) {
  return f(sum, { base: 10 }, [1, 2]);
}

exports.report = function () {
  var lines = [];
  function line(label, thunk) {
    lines.push(label + ": " + describe(thunk));
  }

  line("exported", function () {
    return exportedApply(sum, { base: 1 }, [2, 3]);
  });
  line("guarded", function () {
    return guardedApply(sum, { base: 2 }, [2, 3]);
  });
  line("local", function () {
    return localApply(sum, { base: 3 }, [2, 3]);
  });
  line("maybe", function () {
    return maybeApply(sum, { base: 4 }, [2, 3]);
  });
  line("argument", function () {
    return through(Reflect.apply);
  });
  line("held", function () {
    return held.apply(sum, { base: 5 }, [1, 1]);
  });
  line("call", function () {
    return exportedApply.call(null, sum, { base: 1 }, [2, 3]);
  });
  line("apply", function () {
    return exportedApply.apply(null, [sum, { base: 1 }, [2, 3]]);
  });
  line("bind", function () {
    return exportedApply.bind(null, sum)({ base: 1 }, [2, 3]);
  });
  line("array-like", function () {
    return exportedApply(sum, { base: 1 }, { length: 2, 0: 5, 1: 6 });
  });
  line("arguments", function () {
    return (function () {
      return exportedApply(sum, { base: 1 }, arguments);
    })(7, 8);
  });
  line("extra arguments", function () {
    return exportedApply(sum, { base: 1 }, [2, 3, 4], "ignored");
  });
  line("builtin target", function () {
    return exportedApply(Math.max, null, [1, 9, 4]);
  });
  line("prototype target", function () {
    return exportedApply(Array.prototype.slice, [1, 2, 3], [1]);
  });
  line("identity", function () {
    return [
      exportedApply === Reflect.apply,
      guardedApply === localApply,
      held.apply === exportedApply,
      maybeApply === exportedApply,
      exportedApply === exportedProto,
    ].join(" ");
  });
  line("shape", function () {
    return exportedApply.name + "/" + exportedApply.length + " " + typeof exportedApply;
  });
  line("target not callable", function () {
    return exportedApply(5, null, []);
  });
  line("target missing", function () {
    return exportedApply();
  });
  line("target null", function () {
    return exportedApply(null, null, []);
  });
  line("target a string", function () {
    return exportedApply("ladle", null, []);
  });
  line("target a boolean", function () {
    return exportedApply(true, null, []);
  });
  line("target an object", function () {
    try {
      exportedApply({}, null, []);
    } catch (e) {
      return e.name;
    }
    return "no error";
  });
  line("target before list", function () {
    return exportedApply(5, null, 5);
  });
  line("list a string", function () {
    return exportedApply(sum, { base: 1 }, "ab");
  });
  line("list a function", function () {
    return exportedApply(sum, { base: 1 }, sum);
  });
  line("list missing", function () {
    return exportedApply(sum, { base: 1 });
  });
  line("list null", function () {
    return exportedApply(sum, { base: 1 }, null);
  });
  line("list a number", function () {
    return exportedApply(sum, { base: 1 }, 5);
  });
  line("target throws", function () {
    return exportedApply(
      function () {
        throw new RangeError("from the target");
      },
      null,
      [],
    );
  });

  line("proto of array", function () {
    return exportedProto([]) === Array.prototype;
  });
  line("proto of object", function () {
    return exportedProto({}) === Object.prototype;
  });
  line("proto of bare object", function () {
    return exportedProto(Object.create(null));
  });
  line("proto held", function () {
    return held.proto([]) === exportedProto([]);
  });
  line("proto call", function () {
    return exportedProto.call(null, []) === Array.prototype;
  });
  line("proto apply", function () {
    return exportedProto.apply(null, [{}]) === Object.prototype;
  });
  line("proto of number", function () {
    return exportedProto(5);
  });
  line("proto of nothing", function () {
    return exportedProto();
  });
  line("proto shape", function () {
    return exportedProto.name + "/" + exportedProto.length + " " + typeof exportedProto;
  });
  line("proto identity", function () {
    return [exportedProto === Reflect.getPrototypeOf, held.proto === exportedProto].join(" ");
  });
  line("through apply", function () {
    return exportedApply(exportedProto, null, [[]]) === Array.prototype;
  });
  return lines;
};
